<script setup lang="ts">import{computed,ref}from'vue';import{boxes,type BlindBox}from'../data';import BlindBoxCard from'../components/BlindBoxCard.vue';import DrawModal from'../components/DrawModal.vue';const search=ref(''),selected=ref<string[]>([]),sort=ref('推荐'),chosen=ref<BlindBox|null>(null),count=ref(1),ips=['皮卡丘','伊布','喷火龙','超梦','杰尼龟','烈空坐'];const filtered=computed(()=>{let r=boxes.filter(b=>(!search.value||`${b.name}${b.tags}`.includes(search.value))&&(!selected.value.length||selected.value.some(i=>b.tags.includes(i))));if(sort.value==='价格从低到高')r=[...r].sort((a,b)=>a.price-b.price);if(sort.value==='价格从高到低')r=[...r].sort((a,b)=>b.price-a.price);if(sort.value==='剩余库存')r=[...r].sort((a,b)=>b.remaining-a.remaining);return r});function toggle(i:string){selected.value=selected.value.includes(i)?selected.value.filter(x=>x!==i):[...selected.value,i]}function draw(b:BlindBox,n:number){chosen.value=b;count.value=n}</script>
<template><main><section class="list-hero"><div class="container"><span class="pill gold">宝可梦官方授权</span><h1>精品盲盒专区</h1><p>探索真实有限的收藏卡池，每次开启必得一张卡牌。</p></div></section><section class="container list-page"><aside class="filters card"><div class="field"><label>搜索盲盒或卡牌</label><input v-model="search" placeholder="搜索名称…"></div><div><h3>活动</h3><div class="filter-tags"><button class="active">全部</button><button>新用户福利</button><button>热门</button></div></div><div><h3>宝可梦 IP</h3><div class="ip-list"><button v-for="i in ips" :class="{selected:selected.includes(i)}" @click="toggle(i)"><span>{{i.slice(0,1)}}</span>{{i}}</button></div></div><button class="clear" @click="selected=[];search=''">清除全部条件</button></aside><div class="results"><div class="results-head"><div><b>{{filtered.length}}</b> 个盲盒 <span v-for="i in selected" class="pill gold">{{i}} ×</span></div><select v-model="sort"><option v-for="s in ['推荐','热度','最新上架','价格从低到高','价格从高到低','剩余库存']">{{s}}</option></select></div><div v-if="filtered.length" class="product-grid"><BlindBoxCard v-for="b in filtered" :key="b.id" :box="b" @draw="draw"/></div><div v-else class="empty card"><h2>没有找到符合条件的盲盒</h2><p class="muted">尝试清除筛选或更换搜索关键词。</p><button class="btn btn-primary" @click="selected=[];search=''">清除条件</button></div><button v-if="filtered.length" class="btn load">加载更多</button></div></section><DrawModal :box="chosen" :count="count" @close="chosen=null"/></main></template>
<style scoped>.list-hero{height:330px;color:white;background:linear-gradient(90deg,rgba(20,18,6,.82),rgba(112,93,0,.25)),url('/images/pokemon/rayquaza.png') right 5% center/auto 125% no-repeat,linear-gradient(135deg,#102d42,#176b68 58%,#b8e857);display:flex;align-items:center}.list-hero h1{font-size:48px;margin:14px 0 7px}.list-hero p{color:#eee}.list-page{display:grid;grid-template-columns:230px 1fr;gap:28px;padding:50px 0 80px}.filters{padding:20px;position:sticky;top:92px;align-self:start}.filters h3{font-size:13px;margin-top:28px;border-bottom:1px solid var(--line);padding-bottom:9px}.filter-tags{display:flex;flex-wrap:wrap;gap:7px}.filter-tags button,.clear{border:1px solid var(--line);background:white;border-radius:20px;padding:6px 10px;font-size:11px}.filter-tags .active{background:var(--gold);border-color:var(--gold)}.ip-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.ip-list button{border:1px solid var(--line);background:#fff;border-radius:9px;padding:8px 3px;font-size:11px}.ip-list span{width:28px;height:28px;margin:0 auto 5px;border-radius:50%;background:#f3f2e9;display:grid;place-items:center}.ip-list button.selected{border-color:var(--gold);background:#fffbea}.clear{width:100%;margin-top:24px}.results-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;font-size:13px}.results-head select{border:1px solid var(--line);border-radius:9px;padding:9px;background:white}.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.load{display:flex;margin:38px auto 0;background:white;border:1px solid var(--brown);color:var(--brown);border-radius:30px}@media(max-width:1023px){.product-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:767px){.list-hero{height:260px}.list-hero h1{font-size:36px}.list-page{grid-template-columns:1fr;padding-top:20px}.filters{position:static}.ip-list{grid-template-columns:repeat(3,1fr)}.product-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.product-grid{grid-template-columns:1fr}.results-head{align-items:flex-start;gap:10px}}</style>
